import{_ as m,C as t,o as f,c as h,a3 as s,E as l,j as a,a as i}from"./chunks/framework.BP2ycr77.js";const A=JSON.parse('{"title":"Séance 7 — Les formats de fichiers du Web","description":"","frontmatter":{"title":"Séance 7 — Les formats de fichiers du Web","aside":false},"headers":[],"relativePath":"modules/01-faisabilite/07-formats-de-fichiers.md","filePath":"modules/01-faisabilite/07-formats-de-fichiers.md"}'),x={name:"modules/01-faisabilite/07-formats-de-fichiers.md"};function b(v,e,q,y,_,P){const n=t("DossierPatrick"),r=t("MatricielVectoriel"),o=t("PerteSansPerte"),d=t("QuelFormat"),u=t("EchelleDimensions"),c=t("ComparerQualite"),g=t("VoileContraste"),p=t("TexteRemplacement");return f(),h("div",null,[e[0]||(e[0]=s('<h1 id="seance-7-—-les-formats-de-fichiers-du-web" tabindex="-1">Séance 7 — Les formats de fichiers du Web <a class="header-anchor" href="#seance-7-—-les-formats-de-fichiers-du-web" aria-label="Permalink to &quot;Séance 7 — Les formats de fichiers du Web&quot;">​</a></h1><h2 id="objectifs" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h2><ul><li>Choisir le <strong>format</strong> d&#39;un fichier selon ce qu&#39;il contient et l&#39;endroit où il sera affiché.</li><li>Appliquer les <strong>règles de qualité</strong> de la mise en ligne : poids, dimensions, texte de remplacement, sous-titres, contraste.</li><li>Comprendre ce que demande l&#39;<strong>évaluation 2 : la proposition technique</strong>.</li></ul><h2 id="deroulement-de-la-seance" tabindex="-1">Déroulement de la séance <a class="header-anchor" href="#deroulement-de-la-seance" aria-label="Permalink to &quot;Déroulement de la séance&quot;">​</a></h2><p>La séance se fait en deux temps : <strong>la remise, toute la matière et la présentation de l&#39;évaluation 2 d&#39;abord</strong>, en grand groupe, puis <strong>le reste de la soirée pour le Lab 07</strong>, en équipe.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Heure</th><th style="text-align:left;">Activité</th></tr></thead><tbody><tr><td style="text-align:left;">18 h 30</td><td style="text-align:left;">Remise de l&#39;évaluation 1 et retour sur le Lab 06</td></tr><tr><td style="text-align:left;">18 h 45</td><td style="text-align:left;">Un fichier, trois questions · les formats d&#39;image, de vidéo et de document</td></tr><tr><td style="text-align:left;">19 h 05</td><td style="text-align:left;">Activité 1 — Quel format pour quel fichier ?</td></tr><tr><td style="text-align:left;">19 h 25</td><td style="text-align:left;">Les règles de qualité pour la mise en ligne</td></tr><tr><td style="text-align:left;">19 h 35</td><td style="text-align:left;">Activité 2 — Le texte de remplacement</td></tr><tr><td style="text-align:left;">19 h 50</td><td style="text-align:left;">L&#39;évaluation 2 : la proposition technique</td></tr><tr><td style="text-align:left;">20 h 10</td><td style="text-align:left;">Les consignes du Lab 07 et ce qu&#39;il y a à faire à la maison</td></tr><tr><td style="text-align:left;">20 h 15</td><td style="text-align:left;">Marge pour les questions</td></tr><tr><td style="text-align:left;">20 h 25</td><td style="text-align:left;">Pause</td></tr><tr><td style="text-align:left;">20 h 40</td><td style="text-align:left;"><a href="./../../labs/lab07-alleger-les-medias">Lab 07 — Alléger les médias de Patrick</a>, en équipe, jusqu&#39;à la fin de la soirée</td></tr></tbody></table><p>Le <strong>retour en grand groupe</strong> sur le Lab 07 aura lieu <strong>au début de la séance 8</strong>.</p><hr><h2 id="retour-lab-06" tabindex="-1">Remise de l&#39;évaluation 1 et retour sur le Lab 06 <a class="header-anchor" href="#retour-lab-06" aria-label="Permalink to &quot;Remise de l&#39;évaluation 1 et retour sur le Lab 06 {#retour-lab-06}&quot;">​</a></h2><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Avant de commencer : votre rapport est-il bien sur LÉA ?</strong><br> Ouvrez LÉA et vérifiez que le fichier déposé est le bon : <code>eval1-equipeN-nom1-nom2-nom3.docx</code>, avec les annexes A, B et C. Un fichier vide ou une ancienne version, ça arrive : c&#39;est maintenant qu&#39;on le voit, pas dans deux semaines. </div><p>Avez-vous des <strong>questions de dernière minute</strong> sur l&#39;évaluation 1 ? Posez-les dans le chat.</p><p>Écrivez ensuite dans le chat <strong>le défaut que vous avez corrigé le plus souvent</strong> dans votre rapport, en quelques mots. On regarde ensemble ceux qui reviennent : ce sont les mêmes pièges qui vous attendent dans la proposition technique, où il faudra cette fois <strong>choisir</strong>, chiffrer et justifier.</p><hr><h2 id="un-fichier-trois-questions" tabindex="-1">Un fichier, trois questions <a class="header-anchor" href="#un-fichier-trois-questions" aria-label="Permalink to &quot;Un fichier, trois questions&quot;">​</a></h2><p>Patrick a envoyé ses photos, son logo, un extrait de drone et la grille des tarifs :</p>',15)),l(n),e[1]||(e[1]=s('<p>Avant de choisir un format, posez trois questions sur chaque fichier :</p><ol><li><strong>Qu&#39;est-ce que c&#39;est ?</strong> Une photo, un dessin (logo, icône, carte), une vidéo, un document, une police de caractères.</li><li><strong>Où va-t-il, et à quelle taille ?</strong> Une bannière sur toute la largeur de l&#39;écran, une photo dans le texte, une petite icône dans le menu.</li><li><strong>Qui le regarde, et comment ?</strong> Sur un téléphone, au quai, avec un réseau faible. Avec un lecteur d&#39;écran. En anglais.</li></ol><h3 id="deux-familles-d-images" tabindex="-1">Deux familles d&#39;images <a class="header-anchor" href="#deux-familles-d-images" aria-label="Permalink to &quot;Deux familles d&#39;images&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">Une <strong>image matricielle</strong></th><th style="text-align:left;">Une <strong>image vectorielle</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Ce que c&#39;est</strong></td><td style="text-align:left;">Une grille de pixels, chacun avec sa couleur</td><td style="text-align:left;">Des formes décrites par des calculs : un cercle, une ligne, un texte</td></tr><tr><td style="text-align:left;"><strong>Pour quoi</strong></td><td style="text-align:left;">Les photos</td><td style="text-align:left;">Les logos, les icônes, les pictogrammes</td></tr><tr><td style="text-align:left;"><strong>Si on l&#39;agrandit</strong></td><td style="text-align:left;">Elle devient floue, puis pixelisée</td><td style="text-align:left;">Elle reste nette à toutes les tailles</td></tr><tr><td style="text-align:left;"><strong>Formats</strong></td><td style="text-align:left;">JPEG, PNG, WebP, AVIF</td><td style="text-align:left;">SVG</td></tr></tbody></table>',4)),l(r),e[2]||(e[2]=a("p",null,[i("Une image matricielle se compresse "),a("strong",null,"avec perte"),i(" (on retire des détails que l'œil ne voit presque pas : idéal pour une photo) ou "),a("strong",null,"sans perte"),i(" (on ne retire rien : nécessaire pour du texte et des aplats, où la moindre bavure se voit).")],-1)),l(o),e[3]||(e[3]=s('<h3 id="les-formats-d-image" tabindex="-1">Les formats d&#39;image <a class="header-anchor" href="#les-formats-d-image" aria-label="Permalink to &quot;Les formats d&#39;image&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Format</th><th style="text-align:left;">Pour quoi</th><th style="text-align:center;">Transparence</th><th style="text-align:left;">Ce qu&#39;il faut savoir</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>JPEG</strong></td><td style="text-align:left;">Les photos</td><td style="text-align:center;">Non</td><td style="text-align:left;">Lu partout, depuis toujours. Avec perte. Le repli quand rien d&#39;autre ne fonctionne.</td></tr><tr><td style="text-align:left;"><strong>PNG</strong></td><td style="text-align:left;">Les captures d&#39;écran, les dessins avec du texte, les logos sans SVG</td><td style="text-align:center;">Oui</td><td style="text-align:left;">Sans perte. <strong>Énorme pour une photo</strong> : 5 à 10 fois le poids d&#39;un JPEG.</td></tr><tr><td style="text-align:left;"><strong>WebP</strong></td><td style="text-align:left;">Les photos et les dessins</td><td style="text-align:center;">Oui</td><td style="text-align:left;">Avec ou sans perte. Environ 25 à 35 % plus léger qu&#39;un JPEG de même qualité. Lu par tous les navigateurs actuels.</td></tr><tr><td style="text-align:left;"><strong>AVIF</strong></td><td style="text-align:left;">Les photos</td><td style="text-align:center;">Oui</td><td style="text-align:left;">Encore plus léger que WebP, mais plus lent à produire. Lu par les navigateurs à jour depuis 2024 : on prévoit un repli en WebP ou en JPEG.</td></tr><tr><td style="text-align:left;"><strong>SVG</strong></td><td style="text-align:left;">Les logos, les icônes, les cartes simples</td><td style="text-align:center;">Oui</td><td style="text-align:left;">Vectoriel : quelques Ko, net à toutes les tailles. Inutile pour une photo.</td></tr></tbody></table><p>Deux formats qu&#39;on reçoit souvent, et qu&#39;on ne met <strong>jamais</strong> en ligne tels quels :</p><ul><li><strong>HEIC</strong> : le format des photos d&#39;iPhone. À part Safari, les navigateurs ne l&#39;affichent pas. On le convertit.</li><li><strong>GIF animé</strong> : lourd, limité à 256 couleurs. Une courte vidéo MP4 fait la même chose pour une fraction du poids.</li></ul><h3 id="les-videos" tabindex="-1">Les vidéos <a class="header-anchor" href="#les-videos" aria-label="Permalink to &quot;Les vidéos&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Format</th><th style="text-align:left;">Ce qu&#39;il faut savoir</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>MP4</strong> (codec H.264)</td><td style="text-align:left;">Lu par tous les navigateurs et tous les appareils. Le choix par défaut.</td></tr><tr><td style="text-align:left;"><strong>WebM</strong> (codecs VP9 ou AV1)</td><td style="text-align:left;">Souvent plus léger à qualité égale. Certains appareils Apple plus anciens ne le lisent pas : on l&#39;offre <strong>avec</strong> un MP4 en repli.</td></tr></tbody></table><p>Ce que Patrick envoie, un fichier <strong>.MOV en 4K</strong>, est fait pour le montage, pas pour le Web : une minute de vidéo 4K de drone pèse facilement plusieurs centaines de Mo. Pour une vidéo d&#39;arrière-plan, on retire le son, on réduit à 1920 px de large (souvent 1280 suffisent), on garde 10 à 20 secondes en boucle, et on prévoit une <strong>image d&#39;affiche</strong> (<em>poster</em>) qui s&#39;affiche pendant le chargement.</p><p>Les longues vidéos (une visite guidée de 4 minutes, par exemple) ne s&#39;hébergent généralement pas sur le site lui-même. C&#39;est justement la question Q4 du rapport : vous en avez fait le tour à l&#39;évaluation 1.</p><h3 id="les-documents-et-les-polices" tabindex="-1">Les documents et les polices <a class="header-anchor" href="#les-documents-et-les-polices" aria-label="Permalink to &quot;Les documents et les polices&quot;">​</a></h3><ul><li><strong>PDF</strong> : pour ce qu&#39;on <strong>imprime, signe ou conserve</strong> tel quel (un formulaire de groupe, une décharge à imprimer). Pas pour l&#39;information que tout le monde doit lire : les horaires et les tarifs vont dans la page, en texte. Un PDF <strong>numérisé</strong> est une image : un lecteur d&#39;écran ne peut pas le lire.</li><li><strong>WOFF2</strong> : le format des polices de caractères pour le Web, compressé et lu par tous les navigateurs actuels. Avant de mettre une police en ligne, on vérifie que sa <strong>licence</strong> permet l&#39;usage sur un site. On se limite à deux familles, et à peu de graisses (normal, gras).</li></ul><hr><h3 id="activite-1" tabindex="-1">Activité 1 — Quel format pour quel fichier ? <a class="header-anchor" href="#activite-1" aria-label="Permalink to &quot;Activité 1 — Quel format pour quel fichier ? {#activite-1}&quot;">​</a></h3><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Consigne (10 min, en équipe, puis retour en grand groupe)</strong><br> Huit fichiers, tirés de l&#39;envoi de Patrick et des besoins du mandat. <ol class="list-decimal pl-5"><li>Pour chaque fichier, écrivez en une phrase <strong>pourquoi</strong> vous choisiriez tel format.</li><li>Cliquez ensuite sur le format. Un contour pointillé vert indique le meilleur choix, s&#39;il est différent du vôtre.</li></ol></div>',13)),l(d),e[4]||(e[4]=s('<p><strong>Ce qu&#39;il faut retenir :</strong> le format découle de <strong>ce que contient le fichier</strong>, pas de ce qu&#39;on a reçu. Une photo reste une photo, qu&#39;elle arrive en PNG, en HEIC ou en JPEG; un tableau de prix reste du texte, même numérisé. Et le meilleur format ne sert à rien si le fichier est <strong>six fois trop grand</strong> pour l&#39;endroit où il s&#39;affiche.</p><hr><h2 id="les-regles-de-qualite-pour-la-mise-en-ligne" tabindex="-1">Les règles de qualité pour la mise en ligne <a class="header-anchor" href="#les-regles-de-qualite-pour-la-mise-en-ligne" aria-label="Permalink to &quot;Les règles de qualité pour la mise en ligne&quot;">​</a></h2><h3 id="le-poids-et-les-dimensions" tabindex="-1">Le poids et les dimensions <a class="header-anchor" href="#le-poids-et-les-dimensions" aria-label="Permalink to &quot;Le poids et les dimensions&quot;">​</a></h3><p>Le plus gros gain ne vient pas du format : il vient des <strong>dimensions</strong>. La photo du coucher de soleil fait 6000 px de large; la bannière de l&#39;accueil en affiche au plus 1920. Les 24 millions de pixels de la photo, contre 2,5 millions affichés : le visiteur télécharge <strong>dix fois trop d&#39;image</strong>.</p>',5)),l(u),e[5]||(e[5]=s('<p><strong>La règle du double :</strong> une image n&#39;a pas besoin de faire plus de <strong>deux fois la largeur à laquelle elle s&#39;affiche</strong> (les écrans haute densité affichent deux pixels pour un). Un logo affiché à 200 px : 400 px au plus.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Où va le fichier</th><th style="text-align:center;">Largeur visée</th><th style="text-align:center;">Poids visé</th></tr></thead><tbody><tr><td style="text-align:left;">Bannière ou photo sur toute la largeur</td><td style="text-align:center;">1920 px (2560 au plus)</td><td style="text-align:center;">moins de 300 Ko</td></tr><tr><td style="text-align:left;">Photo dans le texte</td><td style="text-align:center;">1200 px</td><td style="text-align:center;">moins de 150 Ko</td></tr><tr><td style="text-align:left;">Vignette (une carte d&#39;activité, par exemple)</td><td style="text-align:center;">600 px</td><td style="text-align:center;">moins de 60 Ko</td></tr><tr><td style="text-align:left;">Logo, icônes</td><td style="text-align:center;">SVG (sinon 2 × la taille affichée)</td><td style="text-align:center;">moins de 10 Ko</td></tr><tr><td style="text-align:left;">Vidéo d&#39;arrière-plan, sans son, 10 à 20 s</td><td style="text-align:center;">1280 à 1920 px</td><td style="text-align:center;">moins de 4 Mo</td></tr><tr><td style="text-align:left;">Toutes les images de la page d&#39;accueil, ensemble</td><td style="text-align:center;"></td><td style="text-align:center;">moins de 1,5 Mo</td></tr></tbody></table><p>Ces repères ne sont pas des normes officielles. Ce sont des cibles raisonnables, qui aident à respecter l&#39;exigence du rapport : <strong>la page d&#39;accueil s&#39;affiche en moins de 2,5 secondes sur un téléphone</strong>. Avec l&#39;extrait de drone de Patrick tel quel (16 Mo pour 8 secondes), c&#39;est impossible au quai, et difficile même à Trois-Rivières.</p><h3 id="jusqu-ou-compresser" tabindex="-1">Jusqu&#39;où compresser ? <a class="header-anchor" href="#jusqu-ou-compresser" aria-label="Permalink to &quot;Jusqu&#39;où compresser ?&quot;">​</a></h3><p>Une fois la photo à la bonne largeur, le réglage de <strong>qualité</strong> décide du reste. Comparez :</p>',5)),l(c),e[6]||(e[6]=s('<h3 id="l-accessibilite-des-medias" tabindex="-1">L&#39;accessibilité des médias <a class="header-anchor" href="#l-accessibilite-des-medias" aria-label="Permalink to &quot;L&#39;accessibilité des médias&quot;">​</a></h3><p>Le programme d&#39;aide qui a financé les kayaks adaptés exige que l&#39;information sur l&#39;offre adaptée soit « accessible à tous ». La référence, pour le Web, ce sont les règles <strong>WCAG</strong> (<em>Web Content Accessibility Guidelines</em>). Quatre d&#39;entre elles touchent directement les médias :</p><table tabindex="0"><thead><tr><th style="text-align:left;">La règle</th><th style="text-align:left;">Ce qu&#39;elle demande</th><th style="text-align:left;">Pour Aventure Saint-Maurice</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Texte de remplacement</strong> (WCAG 1.1.1)</td><td style="text-align:left;">Chaque image qui informe a un texte qui dit ce qu&#39;elle apporte (l&#39;attribut <code>alt</code>). Une image décorative a un <code>alt</code> vide.</td><td style="text-align:left;">La photo du kayak adapté décrit l&#39;équipement. La photo de décor derrière un titre est sautée.</td></tr><tr><td style="text-align:left;"><strong>Sous-titres</strong> (WCAG 1.2.2)</td><td style="text-align:left;">Une vidéo où l&#39;on parle a des sous-titres (un fichier <code>.vtt</code>, à côté de la vidéo).</td><td style="text-align:left;">La vidéo de sécurité où Patrick explique comment pagayer, en français et en anglais.</td></tr><tr><td style="text-align:left;"><strong>Pause</strong> (WCAG 2.2.2)</td><td style="text-align:left;">Ce qui bouge seul plus de 5 secondes peut être mis en pause.</td><td style="text-align:left;">La vidéo de drone en boucle a un bouton pause visible.</td></tr><tr><td style="text-align:left;"><strong>Contraste</strong> (WCAG 1.4.3)</td><td style="text-align:left;">Le texte se détache du fond : un rapport d&#39;au moins 4,5 pour 1 (3 pour 1 pour un grand titre).</td><td style="text-align:left;">Le titre blanc posé sur la vidéo de drone a besoin d&#39;un voile sombre derrière lui.</td></tr></tbody></table>',3)),l(g),e[7]||(e[7]=s('<h3 id="ce-qu-on-verifie-aussi-avant-de-mettre-une-photo-en-ligne" tabindex="-1">Ce qu&#39;on vérifie aussi avant de mettre une photo en ligne <a class="header-anchor" href="#ce-qu-on-verifie-aussi-avant-de-mettre-une-photo-en-ligne" aria-label="Permalink to &quot;Ce qu&#39;on vérifie aussi avant de mettre une photo en ligne&quot;">​</a></h3><ul><li><strong>Le nom du fichier</strong> : en minuscules, sans espace ni accent, et qui dit ce qu&#39;il contient. <code>via-ferrata-falaise.webp</code>, pas <code>via ferrata FALAISE final(2).png</code>.</li><li><strong>Les personnes sur la photo</strong> : une personne qu&#39;on peut reconnaître doit avoir donné son autorisation (c&#39;est le droit à l&#39;image, au Code civil du Québec). Pour un enfant, c&#39;est le parent qui signe. Rappel : le quart des participants de l&#39;été 2026 étaient mineurs.</li><li><strong>Les métadonnées</strong> : une photo de téléphone peut contenir l&#39;endroit exact où elle a été prise. Squoosh les retire au moment de la compression.</li></ul><h3 id="activite-2" tabindex="-1">Activité 2 — Le texte de remplacement <a class="header-anchor" href="#activite-2" aria-label="Permalink to &quot;Activité 2 — Le texte de remplacement {#activite-2}&quot;">​</a></h3><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Consigne (10 min, en équipe, puis retour en grand groupe)</strong><br> Six images du futur site, chacune à un endroit précis. <ol class="list-decimal pl-5"><li>Choisissez le meilleur texte de remplacement parmi les trois proposés. Une des options peut être un <code>alt</code> vide.</li><li>Si aucun ne vous convient tout à fait, écrivez votre version.</li></ol></div>',4)),l(p),e[8]||(e[8]=s('<p><strong>Ce qu&#39;il faut retenir :</strong> le texte de remplacement ne décrit pas l&#39;image : il dit <strong>ce qu&#39;elle apporte à cet endroit de la page</strong>. La même photo peut mériter une description sur une page et un <code>alt</code> vide sur une autre.</p><hr><h2 id="evaluation-2" tabindex="-1">L&#39;évaluation 2 : la proposition technique <a class="header-anchor" href="#evaluation-2" aria-label="Permalink to &quot;L&#39;évaluation 2 : la proposition technique {#evaluation-2}&quot;">​</a></h2><p>Le rapport que vous venez de remettre décrivait la situation, sans rien recommander. La <strong>proposition technique</strong> tranche : elle complète le même document.</p><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>En bref</strong><br><ul class="list-disc pl-5"><li><strong>Remise :</strong> mercredi <strong>9 décembre, 18 h 30</strong>, sur LÉA (séance 11). 20 %, dont 10 % pour le français.</li><li><strong>Ce qui s&#39;ajoute :</strong> les choix techniques, les formats et les règles de mise en ligne, les adaptations aux contraintes, le temps, l&#39;argent et la recommandation finale.</li><li><strong>Ce qui change dans la partie 1 :</strong> le résumé et la portée sont réécrits, et les commentaires reçus pour l&#39;évaluation 1 sont appliqués.</li></ul><a href="./../../evaluations/evaluation-2"><strong>Lire l&#39;énoncé complet de l&#39;évaluation 2</strong></a></div><p>Ce que chaque séance vous apporte pour la proposition :</p><table tabindex="0"><thead><tr><th style="text-align:center;">Séance</th><th style="text-align:left;">Pour la proposition</th></tr></thead><tbody><tr><td style="text-align:center;">7 (ce soir)</td><td style="text-align:left;">Lab 07 : les <strong>formats</strong> et les règles de mise en ligne (section 9)</td></tr><tr><td style="text-align:center;">8 (18 nov.)</td><td style="text-align:left;">Estimer le <strong>temps</strong> et monter le <strong>devis</strong> (sections 11 et 12). Votre rapport de l&#39;évaluation 1 vous est rendu corrigé</td></tr><tr><td style="text-align:center;">9 (25 nov.)</td><td style="text-align:left;">La <strong>rencontre avec le client</strong> : les réponses à vos questions de la section 7</td></tr><tr><td style="text-align:center;">10 (2 déc.)</td><td style="text-align:left;">Période de questions sur l&#39;évaluation 2</td></tr><tr><td style="text-align:center;">11 (9 déc.)</td><td style="text-align:left;"><strong>Remise</strong> avant 18 h 30</td></tr></tbody></table><p>Votre rapport de l&#39;évaluation 1 vous sera rendu corrigé <strong>au plus tard le 18 novembre</strong>, avec les commentaires à appliquer. D&#39;ici là, commencez par ce qui n&#39;en dépend pas : le choix des outils, à partir de vos essais et de vos tableaux de l&#39;évaluation 1.</p><hr><h2 id="a-faire-maintenant" tabindex="-1">À faire maintenant <a class="header-anchor" href="#a-faire-maintenant" aria-label="Permalink to &quot;À faire maintenant&quot;">​</a></h2><p><a href="./../../labs/lab07-alleger-les-medias">Lab 07 — Alléger les médias de Patrick</a>, en équipe, jusqu&#39;à la fin de la soirée. Téléchargez le dossier de Patrick et la fiche avant la pause : le dossier fait 36 Mo.</p><hr><h2 id="a-faire-a-la-maison" tabindex="-1">À faire à la maison <a class="header-anchor" href="#a-faire-a-la-maison" aria-label="Permalink to &quot;À faire à la maison {#a-faire-a-la-maison}&quot;">​</a></h2><ul><li><strong>Lire l&#39;<a href="./../../evaluations/evaluation-2">énoncé de l&#39;évaluation 2</a></strong> en équipe et noter vos questions : on y répond au début de la séance 8.</li><li><strong>Terminer le Lab 07</strong> si vous n&#39;avez pas eu le temps d&#39;alléger tous les fichiers. La fiche sert directement à la section 9 de la proposition.</li><li><strong>Rassembler vos tableaux de comparaison</strong> de l&#39;évaluation 1, pour votre question et les quatre autres : la section 8 de la proposition part de là.</li></ul><hr><h2 id="avant-la-seance-8-18-novembre" tabindex="-1">Avant la séance 8 (18 novembre) <a class="header-anchor" href="#avant-la-seance-8-18-novembre" aria-label="Permalink to &quot;Avant la séance 8 (18 novembre)&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Copier vos réponses des activités 1 et 2 dans vos notes</span></label></li><li><label><input type="checkbox"><span class="check-text">Déposer la fiche du Lab 07 et vos fichiers allégés dans l&#39;équipe Teams du cours</span></label></li><li><label><input type="checkbox"><span class="check-text">Lire l&#39;énoncé de l&#39;évaluation 2 et écrire vos questions</span></label></li></ul>',17))])}const C=m(x,[["render",b]]);export{A as __pageData,C as default};
